pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < 1e30);
        Actor a = new Actor(c);
        vm.deal(address(a), amount);
        a.depositAmt(amount);        // actor deposits `amount`
        a.withdrawAll(true);         // payout external call FAILS
        a.withdrawAll(false);        // payout external call SUCCEEDS
        // Reference: first attempt reverts (require(callResult)), credit survives;
        // second attempt pays `amount` out, so c holds 0.
        // Mutant: first attempt silently zeroes credit without paying;
        // second attempt sends nothing, so c still holds `amount` != 0.
        assertTrue(address(c).balance == 0, "credit must not be destroyed by a failed payout");
    }
}

contract Actor {
    C c;
    bool failPayout;
    constructor(C _c) { c = _c; }
    function depositAmt(uint256 amt) external {
        c.deposit{value: amt}();
    }
    function withdrawAll(bool fail) external {
        failPayout = fail;
        c.withdrawAll();
    }
    fallback() external payable {
        require(!failPayout, "payout failed");
    }
    receive() external payable {
        require(!failPayout, "payout failed");
    }
}

