pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 extra) public {
        amount = bound(amount, 1, 1e30);
        extra = bound(extra, 1, 1e30);

        ReentrantDepositor attacker = new ReentrantDepositor(c, extra);
        vm.deal(address(attacker), amount + extra);

        // attacker deposits `amount` as its own credit
        vm.prank(address(attacker));
        c.deposit{value: amount}();

        // attacker withdraws; its receive() re-enters and deposits `extra` during the payout
        vm.prank(address(attacker));
        c.withdrawAll();

        // GENERAL RULE: a re-entrant deposit made during withdrawAll must still be
        // credited to the depositor after withdrawAll returns (credit is zeroed
        // exactly once, before the external call). The mutant zeroes credit again
        // after the call, wiping the re-entrant deposit.
        assertTrue(c.credit(address(attacker)) == extra);
    }
}

contract ReentrantDepositor {
    C target;
    uint256 extra;

    constructor(C _target, uint256 _extra) {
        target = _target;
        extra = _extra;
    }

    receive() external payable {
        target.deposit{value: extra}();
    }
}
